import{_ as t,o as d,c as a,a2 as r}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Research index","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/research/README.md"},"headers":[],"relativePath":"sovereign-edge/research/README.md","filePath":"sovereign-edge/research/README.md"}'),o={name:"sovereign-edge/research/README.md"};function c(n,e,i,s,h,l){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="research-index" tabindex="-1">Research index <a class="header-anchor" href="#research-index" aria-label="Permalink to &quot;Research index&quot;">​</a></h1><p>Status at a glance for all Sovereign Edge research notes. Open the individual file for full findings, sources, and open questions.</p><h2 id="what-a-research-doc-is" tabindex="-1">What a research doc is <a class="header-anchor" href="#what-a-research-doc-is" aria-label="Permalink to &quot;What a research doc is&quot;">​</a></h2><p>A research doc captures an open-ended technical or strategic question that doesn&#39;t yet have a concrete, committed design: findings, options considered, and a recommendation — lighter than a formal design doc, and not deleted once decided. It&#39;s the working record of <em>why</em>, kept even after the decision is folded into <a href="./../../CONCEPT.html">CONCEPT.md</a>, <a href="./../epics/">docs/epics/</a>, and <a href="./../../ROADMAP.html">ROADMAP.md</a>.</p><p>Not every research doc needs to conclude with a definitive design — &quot;not now&quot; or &quot;rejected&quot; is a valid, useful outcome to record.</p><p>Each doc carries its metadata (status, scope, date, summary) as YAML frontmatter rather than a bold-label header block — <code>scope</code> here is the platform axis (mobile/desktop/shared), distinct from the <code>summary</code> field&#39;s description of the actual subject matter. Unlike epics, a research doc&#39;s scope is mostly permanent: it describes what the <em>question</em> concerns (RN toolchain choice, phone hardware) more often than where code currently lives, so don&#39;t expect these to migrate the way an epic&#39;s scope can.</p><table tabindex="0"><thead><tr><th>Doc</th><th>Title</th><th>Status</th><th>Scope</th></tr></thead><tbody><tr><td><a href="./0001-concept-and-connector-architecture.html">0001</a></td><td>Sovereign Edge: concept, positioning, and connector architecture</td><td>Decided</td><td>Shared</td></tr><tr><td><a href="./0002-react-native-framework-choice.html">0002</a></td><td>React Native framework choice: Expo vs. Community CLI</td><td>Decided</td><td>Mobile</td></tr><tr><td><a href="./0003-model-verification-hashing.html">0003</a></td><td>Model download verification: why MD5, not SHA-256</td><td>Superseded in part</td><td>Mobile</td></tr><tr><td><a href="./0004-connector-manifest-schema.html">0004</a></td><td>Connector manifest schema: format, validation, and the templating surface</td><td>Decided</td><td>Shared</td></tr><tr><td><a href="./0005-calendar-connector.html">0005</a></td><td>Calendar connector: scope and platform fit</td><td>Decided</td><td>Mobile</td></tr><tr><td><a href="./0006-files-document-summarization.html">0006</a></td><td>Files/document summarization: connector or chat feature?</td><td>Decided (architecture)</td><td>Shared</td></tr><tr><td><a href="./0007-text-to-speech.html">0007</a></td><td>Text-to-speech: chat feature, not a connector</td><td>Decided</td><td>Shared</td></tr><tr><td><a href="./0008-health-step-count.html">0008</a></td><td>Health connector: why &quot;step count&quot; isn&#39;t HealthKit</td><td>Decided (redefine scope)</td><td>Mobile</td></tr><tr><td><a href="./0009-device-connector.html">0009</a></td><td>Device connector: what&#39;s actually left after alarms drop out</td><td>Decided</td><td>Mobile</td></tr><tr><td><a href="./0010-desktop-shell-technology.html">0010</a></td><td>Desktop shell technology: Tauri vs. Electron vs. React Native desktop</td><td>Decided</td><td>Desktop</td></tr><tr><td><a href="./0011-desktop-calendar-connector.html">0011</a></td><td>Desktop calendar connector: platform fit across macOS, Windows, Linux</td><td>Decided</td><td>Shared</td></tr><tr><td><a href="./0012-knowledge-base-and-retrieval.html">0012</a></td><td>Knowledge base and retrieval: where the corpus lives, and what that decides</td><td>Open — decision pending</td><td>Shared</td></tr></tbody></table>',7)])])}const f=t(o,[["render",c]]);export{p as __pageData,f as default};
